142 /// Moving average over windows of `window` consecutive daily counts.
143 pub fn moving_average(daily: &[u32], window: usize) -> Vec<f64> {
144     assert!(window > 0, "window must be positive");
145     let mut out = Vec::new();
146     for end in window..=daily.len() {
147         let sum: u64 = daily[end - window..end].iter().map(|&d| d as u64).sum();
148         out.push(sum as f64 / window as f64);
149     }
150     out
151 }
